<?php
require dirname(__DIR__).'/app/bootstrap.php';
try{$id=integer($_GET['id']??0,1);Commerce::access($id,$_GET['token']??'');$inv=one('SELECT * FROM invoices WHERE order_id=?',[$id]);if(!$inv)fail('Invoice not found.',404);$snap=json_decode($inv['snapshot'],true);$o=$snap['order'];$store=json_decode($o['store_snapshot'],true);$ledger=Commerce::ledger($id);$payments=all("SELECT * FROM payments WHERE order_id=? AND status='confirmed' ORDER BY id",[$id]);$receipt=null;if(isset($_GET['receipt'])){$receipt=one("SELECT * FROM payments WHERE id=? AND order_id=? AND status='confirmed'",[(int)$_GET['receipt'],$id]);if(!$receipt)fail('Only confirmed payments have receipts.',404);}ob_start();require ROOT.'/resources/views/invoice.php';$html=ob_get_clean();if(isset($_GET['pdf'])){$pdf=new Dompdf\Dompdf(['isRemoteEnabled'=>false,'chroot'=>ROOT.'/public','defaultFont'=>'DejaVu Sans']);$pdf->loadHtml($html);$pdf->setPaper('A4');$pdf->render();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.($receipt?'RECEIPT-'.$receipt['id']:$inv['number']).'.pdf"');header('Cache-Control: private, no-store');echo $pdf->output();}else echo $html;}catch(Throwable $e){errorResponse($e);}
